<script lang="ts">
 import {app,run} from '../app.svelte';import {claimStore} from '../store';import {money,total} from '../money';import {todayLocal} from '../sample';import {download,exportCSV} from '../exports';import Icon from '../components/Icon.svelte';import Modal from '../components/Modal.svelte';
 let selected=$state<string[]>([]),date=$state(todayLocal()),mode=$state('Bank transfer'),reference=$state(''),confirm=$state(false);
 const data=$derived(app.data!);const ready=$derived(data.claims.filter(c=>c.status==='Finance approved'));const amount=$derived(total(ready.filter(c=>selected.includes(c.id)).flatMap(c=>c.lines),true));
 async function pay(){const result=await run(()=>claimStore.pay(selected,date,mode,reference,amount),'Payment batch balanced and recorded. Claims marked Paid.');if(result){selected=[];reference='';confirm=false;}}
</script>
<div class="page-header"><div><p class="eyebrow">SETTLE UP WITH CONFIDENCE</p><h1>Payment batches</h1><p>Group approved claims, verify the total, then record reimbursement.</p></div><button onclick={()=>download(exportCSV('batches',data,todayLocal()),'claimease-batches.csv','text/csv')}><Icon name="download" size={17}/>Export batches</button></div>
<div class="notice"><Icon name="info"/><p>This is a payment record, not a payment service. No bank connection, transfer or real money movement takes place.</p></div>
<div class="batch-layout"><section class="panel"><div class="panel-heading"><div><h2>Ready for payment <span class="count">{ready.length}</span></h2><p>Finance-approved claims only.</p></div></div>{#if ready.length}<div class="batch-claims">{#each ready as claim}<label class="batch-claim"><input type="checkbox" value={claim.id} bind:group={selected}/><span><strong>{claim.title}</strong><small>{claim.number} · {data.users.find(u=>u.id===claim.ownerId)?.name}</small></span><strong>{money(total(claim.lines,true))}</strong></label>{/each}</div>{:else}<div class="empty-state"><Icon name="wallet" size={32}/><h3>All caught up</h3><p>Claims appear here after Finance approval.</p><a class="button" href="/finance">Review finance queue</a></div>{/if}</section><section class="panel form-panel"><div class="panel-heading"><h2>New payment batch</h2><Icon name="bank"/></div><label>Payment date<input type="date" bind:value={date} max={todayLocal()}/></label><label>Payment mode<select bind:value={mode}><option>Bank transfer</option><option>UPI</option><option>Cash</option></select></label><label>Payment reference<input bind:value={reference} maxlength="100" placeholder="Your fictional settlement reference"/></label><div class="batch-total"><span>{selected.length} claims selected</span><strong>{money(amount)}</strong><small>Batch total = sum of approved claim amounts</small></div><button class="primary full" disabled={!selected.length||!reference.trim()} onclick={()=>confirm=true}>Record payment<Icon name="check" size={17}/></button></section></div>
<section class="panel"><div class="panel-heading"><div><h2>Recorded batches</h2><p>A permanent record of completed demo reimbursements.</p></div><span class="tag">{data.batches.length} batches</span></div>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (This labelled overflow region requires focus for native arrow-key scrolling; verified by axe and keyboard tests.) -->
<div class="table-scroll" role="region" aria-label="Recorded payment batches" tabindex="0"><table><thead><tr><th>Batch / reference</th><th>Date</th><th>Mode</th><th>Claims</th><th class="num">Paid amount</th></tr></thead><tbody>{#each [...data.batches].reverse() as b}<tr><td><strong>{b.id}</strong><small>{b.reference}</small></td><td>{b.date}</td><td>{b.mode}</td><td>{b.claimIds.length}</td><td class="num"><strong>{money(b.total)}</strong><small class="text-success">✓ Balanced</small></td></tr>{/each}</tbody></table></div></section>
{#if confirm}<Modal title="Confirm payment record" onclose={()=>confirm=false}><p>Record <strong>{money(amount)}</strong> for <strong>{selected.length} claims</strong> on {date}, using {mode}?</p><p>Reference: <strong>{reference}</strong>. The selected claims will become Paid. This action does not send funds and cannot be reversed in the app.</p><div class="modal-actions"><button onclick={()=>confirm=false}>Go back</button><button class="primary" onclick={pay}>Confirm and mark Paid</button></div></Modal>{/if}